// Qalqon service worker — TZ §8.6.
//
// Hand-written rather than generated by @serwist/next: that package's
// webpack-plugin integration doesn't support Turbopack (Next.js 16's
// default bundler — see the warning in @serwist/next's own source,
// node_modules/@serwist/next/src/index.ts), and @serwist/turbopack is
// still experimental. The `serwist` runtime package stays installed for
// a future migration once that support lands; this file implements the
// same strategies by hand against the plain Cache API in the meantime.
//
// Does NOT self.skipWaiting() on install — an update sits "waiting"
// until the client explicitly asks for it (postMessage
// {type: 'SKIP_WAITING'}), so a teacher mid-attendance never gets
// yanked onto a new version without asking. See lib/offline/register-sw.ts.

const VERSION = "v1";
const SHELL_CACHE = `qalqon-shell-${VERSION}`;
const PULL_CACHE = `qalqon-pull-${VERSION}`;
const AVATAR_CACHE = `qalqon-avatars-${VERSION}`;
const OFFLINE_URL = "/offline";

const NETWORK_FIRST_PATHS = ["/api/sync/pull", "/api/me"];
const AVATAR_PATH_HINT = "/storage/v1/object/sign/avatars/";
const MAX_AVATAR_ENTRIES = 500;

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(SHELL_CACHE).then((cache) => cache.add(OFFLINE_URL)));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set([SHELL_CACHE, PULL_CACHE, AVATAR_CACHE]);
      const names = await caches.keys();
      await Promise.all(names.filter((n) => !keep.has(n)).map((n) => caches.delete(n)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return; // mutations always go straight to the network

  const url = new URL(request.url);
  if (url.origin !== self.location.origin && !url.pathname.includes(AVATAR_PATH_HINT)) return;

  if (NETWORK_FIRST_PATHS.some((p) => url.pathname.startsWith(p))) {
    event.respondWith(networkFirst(request, PULL_CACHE, 3000));
    return;
  }

  if (url.pathname.includes(AVATAR_PATH_HINT)) {
    event.respondWith(cacheFirst(request, AVATAR_CACHE));
    return;
  }

  if (url.pathname.startsWith("/api/")) {
    return; // NetworkOnly — never cached, no offline fallback for a raw API call
  }

  if (request.mode === "navigate") {
    event.respondWith(staleWhileRevalidate(request, SHELL_CACHE).catch(() => caches.match(OFFLINE_URL)));
    return;
  }

  event.respondWith(staleWhileRevalidate(request, SHELL_CACHE));
});

async function networkFirst(request, cacheName, timeoutMs) {
  const cache = await caches.open(cacheName);
  try {
    const response = await Promise.race([
      fetch(request),
      new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), timeoutMs)),
    ]);
    if (response.ok) await cache.put(request, response.clone());
    return response;
  } catch {
    const cached = await cache.match(request);
    if (cached) return cached;
    throw new Error("network_first_failed");
  }
}

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (response.ok) {
    await cache.put(request, response.clone());
    await trimCache(cache, MAX_AVATAR_ENTRIES);
  }
  return response;
}

async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);
  return cached ?? (await network) ?? Promise.reject(new Error("stale_while_revalidate_failed"));
}

async function trimCache(cache, maxEntries) {
  const keys = await cache.keys();
  if (keys.length <= maxEntries) return;
  await cache.delete(keys[0]);
}
